      bounds.forEach((b,bi)=>{
        ctx.stroke(...colours[bi]);
        ctx.strokeWeight(1.5);
        b.forEach((p,i)=>ctx.line(...p, ...b[(i+1)%b.length]));
      });
    }
    ctx.pop();
