  },
  //THE OTHER LINE ONE
  (ctx)=>{
    ctx.background(242/255,247/255,255);
    // drawGrid(ctx);
    ctx.noFill();

    ctx.push();
    ctx.scale(lerp(0.1,0.5,comp(t.smoothStep, t.loop)(gt)));
    ctx.push();
    for(let k = 0; k < lerp(80,30,comp(t.smoothStep, t.loop)(gt)); k++) {
      ctx.scale(1.02);
