      });
    };
  })(),
  //THE BOIDS ONE, BUT INSIDE THIS TIME
  (()=>{
    let boids = [...Array(300)].map(()=>({
      point: random(paths.flat()).point,
      heading: [random(),random()],
      colour: colours[Math.random()*colours.length | 0],
    }));
